Chart.defaults.font.family='Inter';Chart.defaults.color='#94A3B8';Chart.defaults.font.size=11;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={view:'hr',tab:{},open:{people:true,recruit:true,attend:true,leave:true,perf:true,analytics:true},dark:false};
let charts=[];
const av=(n,s=32)=>`<img src="https://i.pravatar.cc/96?img=${n}" style="width:${s}px;height:${s}px" class="rounded-full object-cover ring-2 ring-white flex-none" alt="">`;
const avS=ns=>`<div class="flex -space-x-2">${ns.map(n=>av(n,24)).join('')}</div>`;
const PL={emerald:'bg-emerald-50 text-emerald-600',red:'bg-red-50 text-red-500',amber:'bg-amber-50 text-amber-600',blue:'bg-blue-50 text-blue-600',purple:'bg-purple-50 text-purple-600',pink:'bg-pink-50 text-pink-600',slate:'bg-slate-100 text-slate-500',cyan:'bg-cyan-50 text-cyan-600',orange:'bg-orange-50 text-orange-600'};
const pill=(t,c)=>`<span class="pill ${PL[c]||PL.slate}"><span class="dot bg-current opacity-70"></span>${t}</span>`;
const dlt=(v,up=1,c)=>`<span class="inline-flex items-center gap-0.5 text-[11px] font-bold ${up?'text-emerald-500':'text-red-500'}"><i data-lucide="${up?'arrow-up-right':'arrow-down-right'}" class="w-3 h-3"></i>${v}</span>`;
const kpi=(ic,l,v,d,sub,c,up=1)=>`<div class="kcol fadein"><div class="kico bg-${c}-50 text-${c}-500"><i data-lucide="${ic}"></i></div><div class="min-w-0"><p class="text-[11px] font-semibold text-slate-500 truncate">${l}</p><p class="text-[20px] font-extrabold text-slate-900 leading-tight flex items-center gap-1.5">${v} ${d?dlt(d,up):''}</p><p class="text-[10.5px] text-slate-400">${sub}</p></div></div>`;
const ch=(t,r='')=>`<div class="flex items-center justify-between px-4 pt-3.5 pb-2"><h3 class="font-display font-bold text-[14px] text-slate-900">${t}</h3>${r}</div>`;
const vAll=`<button class="text-[11.5px] font-semibold text-brand inline-flex items-center gap-1">View All <i data-lucide="chevron-right" class="w-3.5 h-3.5"></i></button>`;
const drop=(l,i='chevron-down')=>`<button class="inp inline-flex items-center gap-2 !py-1.5 text-slate-600 font-semibold !text-[12px]">${l}<i data-lucide="${i}" class="w-3.5 h-3.5 text-slate-400"></i></button>`;
const hbar=(p,c='emerald',h=6)=>`<div class="h-${h} rounded-full bg-slate-100 overflow-hidden"><div class="h-full rounded-full bg-${c}-500" style="width:${Math.min(p,100)}%"></div></div>`;
const srch=(id,ph)=>`<div class="relative"><i data-lucide="search" class="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2"></i><input class="inp !pl-8 !py-1.5 !text-[12px]" placeholder="${ph}" data-search="${id}"></div>`;
const ftr=(id,ph)=>`<div class="relative flex-1 min-w-[200px]"><i data-lucide="search" class="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2"></i><input class="inp !pl-9 w-full" placeholder="${ph}" data-search="${id}"></div>`;
const pg=(a,b,c)=>`<div class="px-4 py-3 border-t border-slate-100 flex items-center justify-between flex-wrap gap-2"><span class="text-[11.5px] text-slate-400 font-medium">Showing 1 to ${a} of ${b} ${c}</span><div class="flex items-center gap-1"><button class="w-7 h-7 rounded-lg border border-slate-200 flex items-center justify-center"><i data-lucide="chevron-left" class="w-4 h-4 text-slate-500"></i></button><button class="w-7 h-7 rounded-lg bg-brand text-white text-[12px] font-bold">1</button><button class="w-7 h-7 rounded-lg text-[12px] font-bold text-slate-500 hover:bg-slate-50">2</button><button class="w-7 h-7 rounded-lg text-[12px] font-bold text-slate-500 hover:bg-slate-50">3</button><button class="w-7 h-7 rounded-lg text-[12px] font-bold text-slate-500 hover:bg-slate-50">4</button><button class="w-7 h-7 rounded-lg text-[12px] font-bold text-slate-500 hover:bg-slate-50">5</button><span class="text-slate-400 px-1">...</span><button class="px-2 h-7 rounded-lg text-[12px] font-bold text-slate-500 hover:bg-slate-50">${Math.ceil(b/a)}</button><button class="w-7 h-7 rounded-lg border border-slate-200 flex items-center justify-center"><i data-lucide="chevron-right" class="w-4 h-4 text-slate-500"></i></button><button class="inp !py-1 !text-[12px] ml-2">10 / page <i data-lucide="chevron-down" class="w-3 h-3 text-slate-400"></i></button></div></div>`;
const stars=(n)=>{let s='';for(let i=1;i<=5;i++)s+=`<i data-lucide="star" class="w-3.5 h-3.5 ${i<=Math.round(n)?'star fill-amber-400':'text-slate-200'}"></i>`;return `<span class="inline-flex gap-0.5">${s}</span>`;};

