const VIEWS={};const ACTIONS={};
function go(id,sub){
 if(sub)state.sub=sub;else if(SUBVIEW[id])state.sub=SUBVIEW[id];else state.sub=null;
 state.view=id;
 charts.forEach(c=>{try{c.destroy()}catch(e){}});charts=[];
 renderSidebar();renderTopbar();
 const [t,s]=TITLES[id];
 $('#app').innerHTML=`<div class="max-w-[1600px] mx-auto fadein">
  <div class="flex items-start justify-between gap-4 flex-wrap mb-4">
   <div><h1 class="font-display font-extrabold text-[26px] text-slate-900 leading-tight">${t}</h1><p class="text-[13px] text-slate-500 mt-0.5">${s}</p></div>
   <div id="view-actions" class="flex items-center gap-2 flex-none flex-wrap"></div></div>
  <div id="view-body"></div></div>`;
  const __b=VIEWS[id]();const __vb=document.getElementById('view-body');if(__vb){try{__vb.innerHTML=__b;}catch(err){__vb.innerHTML='<div style="padding:2rem;font-family:monospace;color:#b91c1c;font-size:12px"><b>View error:</b> '+(err&&err.message||err)+'</div>';}}
 lucide.createIcons();
 const a=ACTIONS[id];a&&a();
 bindTabs();bindSearch();
 $('#app').scrollTop=0;
}
function mkChart(id,cfg){const el=document.getElementById(id);if(el)charts.push(new Chart(el,cfg));}
function bindTabs(){$$('[data-tabgroup]').forEach(g=>{const key=g.dataset.tabgroup;const cur=state.tab[key]||g.dataset.default||(g.querySelector('[data-tab]')||{}).dataset?.tab;g.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===cur));document.querySelectorAll(`[data-pane="${key}"]`).forEach(p=>p.classList.toggle('hidden',p.dataset.paneid!==cur));});}
function bindSearch(){
 const gs=$('#global-search');
 if(gs&&!gs.dataset.bound){gs.dataset.bound='1';gs.oninput=()=>{const q=gs.value.toLowerCase();$$('#app table tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none');};}
 $$('[data-search]').forEach(inp=>{if(inp.dataset.bound)return;inp.dataset.bound='1';inp.oninput=()=>{const q=inp.value.toLowerCase();const tbl=document.getElementById(inp.dataset.search);if(!tbl)return;tbl.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none');};});
}
document.addEventListener('click',e=>{
 const g=e.target.closest('[data-go]');
 if(g){const grp=g.dataset.go;if(g.dataset.sub){go(grp,g.dataset.sub);}else{state.open[grp]=state.open[grp]===undefined?true:!state.open[grp];if(!GROUPS.find(x=>x.id===grp).children){go(grp);}else{renderSidebar();lucide.createIcons();}}return;}
 const tb=e.target.closest('[data-tab]');
 if(tb){const gp=tb.closest('[data-tabgroup]');state.tab[gp.dataset.tabgroup]=tb.dataset.tab;bindTabs();return;}
 const sw=e.target.closest('.switch');
 if(sw){sw.classList.toggle('on');return;}
 const ap=e.target.closest('[data-approve]');
 if(ap){const tr=ap.closest('tr');tr.querySelector('[data-stc]').innerHTML=pill('Approved','emerald');toast('Leave request approved');return;}
 const rj=e.target.closest('[data-reject]');
 if(rj){const tr=rj.closest('tr');tr.querySelector('[data-stc]').innerHTML=pill('Rejected','red');toast('Leave request rejected');return;}
 const tk=e.target.closest('[data-tk]');
 if(tk){const tr=tk.closest('tr');tr.querySelector('[data-tkc]').innerHTML=pill(tk.dataset.tk==='1'?'Completed':'Pending',tk.dataset.tk==='1'?'emerald':'amber');toast('Task updated');return;}
 const conn=e.target.closest('[data-toast]');if(conn){toast(conn.dataset.toast);return;}
});
function toast(m){const t=document.createElement('div');t.className='fixed bottom-5 right-5 z-[70] bg-ink text-white text-[13px] font-semibold px-4 py-2.5 rounded-xl shadow-lg fadein flex items-center gap-2';t.innerHTML=`<i data-lucide="check-circle" class="w-4 h-4 text-emerald-400"></i>${m}`;document.body.appendChild(t);lucide.createIcons();setTimeout(()=>{t.style.opacity='0';t.style.transition='opacity .3s';setTimeout(()=>t.remove(),300);},2200);}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#global-search')?.focus();}});

