/* ================= AI HR ASSISTANT ================= */
VIEWS.ai=()=>{
 $('#view-actions').innerHTML=`<span class="pill bg-purple-50 text-purple-600 !py-1.5 !px-3"><i data-lucide="sparkles" class="w-3.5 h-3.5"></i>Powered by AI</span>`;
 return `<p class="text-[11.5px] text-slate-400 mb-3 flex items-center gap-1.5 -mt-2"><i data-lucide="house" class="w-3.5 h-3.5"></i>HR <i data-lucide="chevron-right" class="w-3 h-3"></i>Analytics <i data-lucide="chevron-right" class="w-3 h-3"></i><span class="text-slate-600 font-semibold">AI HR Assistant</span></p>
 <div class="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-3 mb-4">${[['message-circle','purple','Get Instant Answers','Ask any HR policy, process or data-related question'],['chart-bar','emerald','Analyze Your Data','Get insights from your HR data in seconds'],['zap','amber','Automate Tasks','Create reports, send reminders, and more'],['file-text','red','Policy Guidance','Get accurate company policy information'],['user','blue','Personalized Support','Tailored suggestions for your organization']].map(([ic,c,t,s])=>`<div class="card p-4"><div class="kico bg-${c}-50 text-${c}-500 mb-2"><i data-lucide="${ic}"></i></div><p class="font-bold text-[12.5px]">${t}</p><p class="text-[10.5px] text-slate-400 leading-snug mt-0.5">${s}</p></div>`).join('')}</div>
 <div class="grid grid-cols-1 lg:grid-cols-[240px_1fr_260px] gap-4">
  <div class="card overflow-hidden max-h-[calc(100vh-300px)] flex flex-col"><button class="btn-p !rounded-none justify-center !py-2.5" onclick="toast('New chat started')"><i data-lucide="plus" class="w-4 h-4"></i>New Chat</button>
   <div class="p-3 border-b border-slate-100"><div class="relative"><i data-lucide="search" class="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2"></i><input class="inp !pl-8 !py-1.5 w-full" placeholder="Search chats..."></div></div>
   <div class="flex-1 overflow-y-auto p-2"><p class="px-2 pt-1 pb-1.5 text-[9.5px] font-extrabold uppercase tracking-wider text-slate-400">Recent Chats</p>
    ${[['Headcount by Department','Today, 04:28 PM',1],['Attrition Analysis','Today, 12:14 PM',0],['Leave Trend Report','Yesterday, 05:42 PM',0],['Recruitment Pipeline','Yesterday, 03:10 PM',0],['Payroll Cost Analysis','28 Sep 2026',0],['Employee Engagement','27 Sep 2026',0],['Policy: Work From Home','27 Sep 2026',0],['Generate Custom Report','26 Sep 2026',0]].map(([t,d,a])=>`<div class="flex items-center gap-2.5 px-2 py-2 rounded-lg cursor-pointer ${a?'bg-blue-50/70':'hover:bg-slate-50'}"><i data-lucide="message-circle" class="w-4 h-4 ${a?'text-brand':'text-slate-400'} flex-none"></i><div class="flex-1 min-w-0"><p class="text-[11.5px] font-bold ${a?'text-brand':'text-slate-700'} truncate">${t}</p><p class="text-[9.5px] text-slate-400">${d}</p></div></div>`).join('')}</div></div>
  <div class="card overflow-hidden flex flex-col max-h-[calc(100vh-300px)]"><div class="px-4 py-3 border-b border-slate-100 flex items-center gap-3"><span class="w-9 h-9 rounded-xl bg-purple-100 flex items-center justify-center"><i data-lucide="bot" class="w-5 h-5 text-purple-600"></i></span><div class="flex-1"><p class="font-display font-bold text-[14px]">AI HR Assistant</p><p class="text-[10px] text-slate-400 flex items-center gap-1.5"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>Online · I can help you with HR data analysis, company policies, report generation, and more.</p></div><button class="btn-o !py-1.5 !text-[12px]" onclick="toast('New chat started')"><i data-lucide="message-square" class="w-3.5 h-3.5"></i>New Chat</button><button class="w-8 h-8 rounded-lg hover:bg-slate-100 flex items-center justify-center"><i data-lucide="more-vertical" class="w-4 h-4 text-slate-500"></i></button></div>
   <div class="flex-1 overflow-y-auto p-4 space-y-5 bg-slate-50/50" id="ai-chat">
    <div class="flex justify-end gap-3">${av(45,32)}<div class="max-w-[75%]"><div class="msg-out"><p>Show me the employee headcount by department for the last 6 months</p></div><p class="text-[9.5px] text-slate-400 mt-1 text-right">04:28 PM <i data-lucide="check-check" class="w-3 h-3 inline text-blue-500"></i></p></div></div>
    <div class="flex gap-3"><span class="w-9 h-9 rounded-xl bg-purple-100 flex items-center justify-center flex-none"><i data-lucide="bot" class="w-5 h-5 text-purple-600"></i></span><div class="min-w-0 flex-1"><div class="msg-in !max-w-full"><p class="mb-2">Here is the employee headcount by department for the last 6 months:</p>
     <div class="rounded-xl border border-slate-200 overflow-hidden"><div class="px-3 py-2 border-b border-slate-100 flex items-center justify-between"><div><p class="font-bold text-[12.5px]">Employee Headcount by Department</p><p class="text-[9.5px] text-slate-400">Total active employees | Last 6 Months</p></div></div>
     <div class="p-3"><canvas id="c-ai" height="170"></canvas>
     <div class="flex justify-center gap-4 pt-2 text-[10.5px] font-semibold text-slate-500 flex-wrap"><span class="flex items-center gap-1.5"><span class="w-2.5 h-2.5 rounded-full bg-blue-400"></span>Engineering</span><span class="flex items-center gap-1.5"><span class="w-2.5 h-2.5 rounded-full bg-emerald-400"></span>Marketing</span><span class="flex items-center gap-1.5"><span class="w-2.5 h-2.5 rounded-full bg-amber-400"></span>Operations</span><span class="flex items-center gap-1.5"><span class="w-2.5 h-2.5 rounded-full bg-purple-400"></span>HR</span><span class="flex items-center gap-1.5"><span class="w-2.5 h-2.5 rounded-full bg-rose-400"></span>Finance</span></div></div></div>
     <div class="flex gap-2 mt-3 flex-wrap"><button class="btn-o !py-1.5 !text-[11.5px]" data-toast="Opening full report"><i data-lucide="chart-bar" class="w-3.5 h-3.5"></i>View Full Report</button><button class="btn-o !py-1.5 !text-[11.5px]" data-toast="Loading location breakdown"><i data-lucide="pie-chart" class="w-3.5 h-3.5"></i>Breakdown by Location</button><button class="btn-o !py-1.5 !text-[11.5px]" data-toast="Exporting to Excel"><i data-lucide="download" class="w-3.5 h-3.5"></i>Export to Excel</button><button class="w-8 h-8 rounded-lg border border-slate-200 flex items-center justify-center"><i data-lucide="more-horizontal" class="w-4 h-4 text-slate-400"></i></button></div></div>
     <p class="text-[9.5px] text-slate-400 mt-1">04:28 PM</p></div></div>
    <div><p class="text-[11px] font-extrabold text-slate-500 mb-2 flex items-center gap-1.5"><i data-lucide="sparkles" class="w-3.5 h-3.5 text-purple-500"></i>Suggested Next Questions</p>
     <div class="flex flex-wrap gap-2">${['Show attrition rate by department','List employees with low attendance','Generate a recruitment pipeline report','Show leave trend for this quarter'].map(q=>`<button class="pill bg-white border border-slate-200 text-slate-600 !font-semibold hover:border-brand hover:text-brand" onclick="askAI('${q}')">${q}</button>`).join('')}<button class="w-8 h-8 rounded-full border border-slate-200 flex items-center justify-center" data-toast="Regenerating suggestions"><i data-lucide="refresh-cw" class="w-3.5 h-3.5 text-slate-400"></i></button></div></div>
   </div>
   <div class="p-3 border-t border-slate-100"><div class="flex items-center gap-2"><button class="w-8 h-8 rounded-lg hover:bg-slate-100 flex items-center justify-center flex-none"><i data-lucide="paperclip" class="w-4 h-4 text-slate-500"></i></button>
   <input class="inp flex-1 !py-2.5 !rounded-full" placeholder="Ask anything about your HR data, policies, or reports..." id="ai-input"><button class="w-10 h-10 rounded-full bg-brand flex items-center justify-center flex-none hover:bg-blue-700" onclick="sendAI()"><i data-lucide="send" class="w-4 h-4 text-white"></i></button></div>
   <p class="text-[9px] text-slate-400 text-center mt-2">AI HR Assistant can make mistakes. Please verify important information.</p></div></div>
  <div class="space-y-4">
   <div class="card">${ch('Quick Actions')}<div class="px-4 pb-4 grid grid-cols-3 gap-2">${[['chart-bar','Generate Report','blue'],['file-text','Summarize Data','purple'],['book-open','Find Policy','emerald'],['mail','Draft Email','amber'],['trending-up','Analyze Trends','red'],['copy','Compare Data','cyan']].map(([ic,t,c])=>`<button class="rounded-xl bg-${c}-50 py-3 flex flex-col items-center gap-1.5 hover:shadow-md transition" data-toast="${t}"><i data-lucide="${ic}" class="w-5 h-5 text-${c}-500"></i><span class="text-[9.5px] font-bold text-slate-700 text-center leading-tight">${t}</span></button>`).join('')}</div></div>
   <div class="card">${ch('Common Questions',vAll)}<div class="px-2 pb-3">${['What is our current headcount?','How many employees are on leave today?','Show attendance summary for this month','What is the attrition rate?','List employees joining this week','Show department wise salary cost','Generate recruitment status report','What is our overtime trend?'].map(q=>`<button class="w-full flex items-center gap-2 px-2 py-2 hover:bg-slate-50 rounded-lg text-left" onclick="askAI('${q}')"><i data-lucide="chevron-right" class="w-3.5 h-3.5 text-slate-300"></i><span class="flex-1 text-[11.5px] font-bold text-slate-700">${q}</span></button>`).join('')}</div></div>
   <div class="card">${ch('Try These Prompts','<p class="text-[10px] text-slate-400 font-medium">Use these ready prompts to get started</p>')}<div class="px-2 pb-3">${['Show me top 10 employees with highest performance rating','Compare this quarter\'s attendance with last quarter','Create a monthly leave report for all departments'].map(q=>`<button class="w-full flex items-start gap-2 px-2 py-2.5 hover:bg-slate-50 rounded-lg text-left" onclick="askAI('${q.replace(/'/g,"\\'")}')"><span class="flex-1 text-[11px] font-semibold text-slate-600 leading-snug">${q}</span><i data-lucide="arrow-up-right" class="w-3.5 h-3.5 text-brand flex-none mt-0.5"></i></button>`).join('')}</div></div>
  </div>
 </div>`;
};
function sendAI(){const inp=$('#ai-input');if(!inp||!inp.value.trim())return;askAI(inp.value);inp.value='';}
function askAI(q){
 const wrap=$('#ai-chat');if(!wrap)return;
 const u=document.createElement('div');u.className='flex justify-end gap-3 fadein';u.innerHTML=`${av(45,32)}<div class="max-w-[75%]"><div class="msg-out"><p>${q.replace(/</g,'&lt;')}</p></div><p class="text-[9.5px] text-slate-400 mt-1 text-right">now <i data-lucide="check" class="w-3 h-3 inline text-slate-400"></i></p></div>`;wrap.appendChild(u);
 const t=document.createElement('div');t.className='flex gap-3 fadein';t.innerHTML=`<span class="w-9 h-9 rounded-xl bg-purple-100 flex items-center justify-center flex-none"><i data-lucide="bot" class="w-5 h-5 text-purple-600"></i></span><div class="msg-in"><p class="flex items-center gap-1.5 text-slate-400"><span class="w-1.5 h-1.5 rounded-full bg-purple-400 animate-bounce"></span><span class="w-1.5 h-1.5 rounded-full bg-purple-400 animate-bounce" style="animation-delay:.15s"></span><span class="w-1.5 h-1.5 rounded-full bg-purple-400 animate-bounce" style="animation-delay:.3s"></span></p></div>`;wrap.appendChild(t);wrap.scrollTop=wrap.scrollHeight;lucide.createIcons();
 setTimeout(()=>{t.querySelector('.msg-in').innerHTML=`<p>Here's what I found for <b>"${q.replace(/</g,'&lt;')}"</b>:</p><div class="mt-2 rounded-xl bg-slate-50 border border-slate-100 p-3 space-y-1.5 text-[11.5px]">${[['Total Employees','48'],['Active This Quarter','46'],['New Joins','6'],['On Leave Today','7']].map(([k,v])=>`<div class="flex justify-between"><span class="text-slate-500 font-medium">${k}</span><b>${v}</b></div>`).join('')}</div><div class="flex gap-2 mt-3"><button class="btn-o !py-1 !text-[11px]" onclick="toast('Opening full report')">View Full Report</button><button class="btn-o !py-1 !text-[11px]" onclick="toast('Exporting to Excel')">Export to Excel</button></div>`;wrap.scrollTop=wrap.scrollHeight;lucide.createIcons();},1200);
}
ACTIONS.ai=()=>{mkChart('c-ai',{type:'bar',data:{labels:['Apr 2026','May 2026','Jun 2026','Jul 2026','Aug 2026','Sep 2026'],datasets:[{label:'Engineering',data:[120,125,132,138,142,148],backgroundColor:'#60A5FA',borderRadius:2},{label:'Marketing',data:[85,88,90,92,95,98],backgroundColor:'#34D399',borderRadius:2},{label:'Operations',data:[62,65,68,70,72,74],backgroundColor:'#FBBF24',borderRadius:2},{label:'HR',data:[48,50,52,55,58,60],backgroundColor:'#A78BFA',borderRadius:2},{label:'Finance',data:[35,38,40,42,44,46],backgroundColor:'#FB7185',borderRadius:2}]},options:{plugins:{legend:{display:false}},scales:{y:{grid:{color:'#F1F5F9'},ticks:{maxTicksLimit:5}},x:{grid:{display:false},ticks:{font:{size:9}}}}}});};
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='ai-input'){e.preventDefault();sendAI();}if(e.key==='Enter'&&e.target.id==='chat-input'){e.preventDefault();sendChat();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-timer-toggle]');if(b){const running=b.dataset.on!=='0';b.dataset.on=running?'0':'1';b.innerHTML=running?'<i data-lucide="play" class="w-4 h-4"></i>Resume':'<i data-lucide="pause" class="w-4 h-4"></i>Pause';lucide.createIcons();}});


/* ===== LIVE TIMER TICKER ===== */
setInterval(()=>{$$('[data-timer]').forEach(el=>{const p=(el.textContent||'00:00:00').split(':');let h=+p[0]||0,m=+p[1]||0,s=+p[2]||0;s++;if(s>59){s=0;m++;}if(m>59){m=0;h++;}el.textContent=[h,m,s].map(v=>String(v).padStart(2,'0')).join(':');});},1000);

/* ================= BOOT ================= */

/* ===== CROSS-APP ROLE SWITCHER (admin <-> hr <-> manager) ===== */
(function(){
  const HERE=(typeof location!=='undefined'?(location.pathname.split('/').pop()||''):'').toLowerCase();
  const APPS=[['admin','Admin Console','Team management & productivity','layout-dashboard'],
              ['hr','HR Suite','People, recruitment, attendance & payroll','users'],
              ['manager','Manager View','My team, tasks, approvals & reports','user-check'],
              ['employee','Employee Portal','My tasks, time, leave & payroll','circle-check']];
  const menu=document.createElement('div');
  menu.id='role-menu';
  menu.className='hidden card p-2 z-[80]';
  menu.style.cssText='position:fixed;box-shadow:0 12px 32px rgba(2,6,23,.35);min-width:230px';
  menu.innerHTML=`<p class="px-2 pt-1 pb-1.5 text-[10px] font-extrabold uppercase tracking-wider text-slate-400">Switch workspace</p>`+
    APPS.map(([f,t,s,ic])=>`<a href="${f}" class="flex items-center gap-2.5 px-2 py-2 rounded-lg hover:bg-slate-50 ${f===HERE?'bg-blue-50/70':''}">
      <span class="w-8 h-8 rounded-lg flex items-center justify-center flex-none ${f===HERE?'bg-brand':'bg-slate-100'}"><i data-lucide="${ic}" class="w-4 h-4 ${f===HERE?'text-white':'text-slate-500'}"></i></span>
      <span class="flex-1 min-w-0"><p class="text-[12.5px] font-bold text-slate-800">${t}</p><p class="text-[9.5px] text-slate-400 truncate">${s}</p></span>
      ${f===HERE?'<i data-lucide="check" class="w-4 h-4 text-brand flex-none"></i>':''}</a>`).join('');
  document.body.appendChild(menu);
  document.addEventListener('click',e=>{
    const btn=e.target.closest('#role-btn');
    if(btn){e.preventDefault();e.stopPropagation();
      const wasHidden=menu.classList.contains('hidden');
      menu.classList.remove('hidden');lucide.createIcons();
      const r=btn.getBoundingClientRect();
      menu.style.left=r.left+'px';menu.style.width=Math.max(r.width,230)+'px';
      menu.style.top=(r.top-menu.offsetHeight-8)+'px';
      if(!wasHidden)menu.classList.add('hidden');
      return;}
    if(!e.target.closest('#role-menu'))menu.classList.add('hidden');
  });
})();


/* ===== ANTI-BLANK BOOT GUARD ===== */
window.addEventListener&&window.addEventListener('error',e=>{const a=document.getElementById('app');if(a&&(!a.innerHTML||!a.innerHTML.trim()))a.innerHTML='<div style="padding:3rem;font-family:monospace;font-size:13px;color:#b91c1c"><b>Startup error:</b> '+(e.message||'unknown')+'<br><br>If you see this after an update, hard-refresh with Ctrl+Shift+R to clear the cached copy.</div>';});
function __boot(viewId){try{go(viewId);}catch(err){const a=document.getElementById('app');if(a)a.innerHTML='<div style="padding:3rem;font-family:monospace;font-size:13px;color:#b91c1c"><b>Render error:</b> '+(err&&err.message||err)+'</div>';}}

__boot('hr');